    # events: list of dicts: {'job_id': ..., 'state': ..., 'at': ...}
    job_events = {}
    for ev in events:
        job_id = ev['job_id']
        if job_id not in job_events:
            job_events[job_id] = []
        job_events[job_id].append(ev)

    stuck_jobs = []
    for job_id, evs in job_events.items():
        # Find latest event (most recent)
        latest = max(evs, key=lambda e: e['at'])
        # If latest state is queued or completed, never stuck
        if latest['state'] in ('queued', 'completed'):
            continue
        # If latest state is running, check if older than grace
        if latest['state'] == 'running':
            # now - at > grace ?
            if now - latest['at'] > grace:
                stuck_jobs.append(job_id)
            # equal to grace is not stuck, less is not stuck
    return sorted(stuck_jobs)"}}}]
